/****************************************************************************
 * Name: bk7258_wifi_scan_acquire / _release / _get
 *
 * Description:
 *   Hold the vendor's scan result set for the length of one enumeration.
 *
 *   These used to be a single bk7258_wifi_scan_get() that did
 *   sr_get_scan_results() and sr_release_scan_results() around every item,
 *   which destroyed the results on the first call.  The pairing is not a
 *   lock, it is a reference count, and rw_msg_rx.c:199 frees everything when
 *   it reaches zero:
 *
 *       ptr->ref -= 1;
 *       if (ptr->ref) goto release_exit;
 *       sr_free_all(ptr);
 *       scan_rst_set_ptr = 0;
 *
 *   The set arrives from the scan with ref 0, so get/release around item 0
 *   took it to 1 and straight back to 0 -- freeing all the results and
 *   nulling the global before item 1 was ever asked for.  On the board that
 *   showed up as wapi's two ioctls reporting 21 results and then 0: the
 *   first is wapi_scan_stat()'s one-byte probe, which reaches exactly one
 *   scan_get() before running out of buffer.
 *
 *   Acquire once, walk, release once.  The vendor's own callers do the same
 *   (hostapd_intf.c:549 holds the pointer across the whole upload).
 *
 ****************************************************************************/

static SCAN_RST_UPLOAD_T *g_bk7258_scan_set;

int bk7258_wifi_scan_acquire(void)
{
  if (g_bk7258_scan_set != NULL)
    {
      return -1;
    }

  g_bk7258_scan_set = (SCAN_RST_UPLOAD_T *)sr_get_scan_results();
  if (g_bk7258_scan_set == NULL)
    {
      return 0;
    }

  return (int)g_bk7258_scan_set->scanu_num;
}

void bk7258_wifi_scan_release(void)
{
  if (g_bk7258_scan_set != NULL)
    {
      sr_release_scan_results(g_bk7258_scan_set);
      g_bk7258_scan_set = NULL;
    }
}

